// ---------------------------------------------------------------------------
// Decoding helpers. Error messages name the JSON path, never the value,
// so a malformed response cannot leak personal data into logs.
// ---------------------------------------------------------------------------

T _cast<T extends Object>(Object? value, String path) {
  if (value is T) {
    return value;
  }
  throw FormatException(
    value == null ? '$path is missing' : '$path has an unexpected type',
  );
}

List<T> _castList<T>(
  Object? value,
  String path,
  T Function(Object? item, String itemPath) decode,
) {
  final List<Object?> list = _cast<List<Object?>>(value, path);
  return List<T>.unmodifiable(<T>[
    for (int i = 0; i < list.length; i++) decode(list[i], '$path[$i]'),
  ]);
}

Map<String, T> _castMap<T>(
  Object? value,
  String path,
  T Function(Object? item, String itemPath) decode,
) {
  final Map<String, Object?> map = _cast<Map<String, Object?>>(value, path);
  return Map<String, T>.unmodifiable(<String, T>{
    for (final MapEntry<String, Object?> e in map.entries)
      e.key: decode(e.value, '$path.${e.key}'),
  });
}

DateTime _parseDateTime(String value, String path) {
  final DateTime? parsed = DateTime.tryParse(value);
  if (parsed == null) {
    throw FormatException('$path is not an RFC 3339 date-time');
  }
  return parsed;
}

bool _listEquals<T>(List<T>? a, List<T>? b) {
  if (identical(a, b)) {
    return true;
  }
  if (a == null || b == null || a.length != b.length) {
    return false;
  }
  for (int i = 0; i < a.length; i++) {
    if (a[i] != b[i]) {
      return false;
    }
  }
  return true;
}

int _listHash<T>(List<T>? list) => list == null ? 0 : Object.hashAll(list);

bool _mapEquals<T>(Map<String, T>? a, Map<String, T>? b) {
  if (identical(a, b)) {
    return true;
  }
  if (a == null || b == null || a.length != b.length) {
    return false;
  }
  for (final MapEntry<String, T> e in a.entries) {
    if (!b.containsKey(e.key) || b[e.key] != e.value) {
      return false;
    }
  }
  return true;
}

int _mapHash<T>(Map<String, T>? map) => map == null
    ? 0
    : Object.hashAllUnordered(<int>[
        for (final MapEntry<String, T> e in map.entries)
          Object.hash(e.key, e.value),
      ]);
